#!/usr/bin/python3
# Generated by Ask CK PyTest Creator for AWPTCM-T33233 — Port - Auto Negotiation
# Standardized ART framework script. Frame is fixed; test logic is filled per step.
#
# ==== OBJECTIVE — expected results this script must demonstrate ====
#   - A port with no pluggable present defaults to automatic speed and duplex negotiation.
#   - Inserting a supported pluggable results in successful autonegotiation and link
#   establishment.
#   - A port configured for Auto speed and duplex establishes a link with a compliant link
#   partner.
#   - Link establishment succeeds when one side is set to Auto and the partner is forced to
#   a supported speed or duplex.
#   - An incompatible or unsupported partner configuration causes negotiation to fail
#   predictably — no link is established (or it is correctly reported as down) — rather than
#   settling into an inconsistent or unstable state.
#   - The port accurately reports Auto mode together with the negotiated speed and duplex
#   values.
#   - Link status is correctly reported as up once autonegotiation completes.
#   - After a change that affects negotiation, the port renegotiates and re-resolves cleanly
#   to a valid outcome, without retaining stale negotiated state.
#   - Automatic speed and duplex negotiation produces a working link across all supported
#   configurations with a compliant partner.
# ==================================================================

import sys
import time
from framework import ATTestSet, ATTestCase
from framework import ATDrivers


class TestSet(ATTestSet.TestSet):

    FEATURES = ['ALL']

    def _ck_bind_link(self, setup, dut, misc, role):
        """Resolve `[misc] ck_link_<role>` on THIS bench, bind it, and assert its media.

        Fixed frame — do not edit or delete. Three failures it converts from silent to loud:
          1. an undeclared role: the bench has not agreed to host this test;
          2. `init_portlink()` returning (None, None) for a link the bench does not have —
             a None port later renders as `interface None`, so the run fails looking like a
             SCRIPT defect;
          3. the bound port being the wrong MEDIA. That one cannot be caught offline: media
             belongs to the pluggable, and the CLI accepts `polarity`/`speed 100` on fibre
             where they are meaningless, so the run would report a PRODUCT failure that is
             really a cabling error.
        Raising aborts the suite on purpose: "this bench cannot host this test" is not a
        test result. See ask-ck/pytest-create/TOPOLOGY-PROFILES.md.
        """
        import ck_media
        ref = misc.get('ck_link_' + role)
        if not ref:
            raise RuntimeError(
                "BENCH PROBLEM, not a product defect: this .setup declares no "
                "ck_link_%s, so the %s link this test needs is not available here. "
                "See TOPOLOGY-PROFILES.md." % (role, role))
        dev_a, dev_b, _named_port = ck_media.parse_link_ref(ref)
        dut_key = misc.get('ck_role_dut', 'swi_a')
        far_key = dev_b if dev_a == dut_key else dev_a
        far = setup.init_swi(far_key)
        (near_port, far_port) = setup.init_portlink(dut, far, type1='port', type2='port')
        if near_port is None or far_port is None:
            raise RuntimeError(
                "BENCH PROBLEM, not a product defect: ck_link_%s = %r but no unused "
                "matching [portlink] exists between %s and %s." % (role, ref, dut_key, far_key))
        status = dut.cmd('show interface %s status' % near_port.name)
        ok, why = ck_media.assert_role_media(status, near_port.name, role)
        if not ok:
            raise RuntimeError(why)
        self.log('topology: role %r -> %s %s <-> %s %s (%s)' % (
            role, dut_key, near_port.name, far_key, far_port.name, why))
        return near_port, far_port, far

    def init(self, setup):
        # Topology is resolved from the .setup [misc] ROLE CONTRACT at run time, so this
        # script names no device and no port: it binds correctly on any bench that declares
        # the roles it needs, and fails loudly on one that does not. The role names come
        # from TOPOLOGY-PROFILES.md; the bench says what they mean HERE.
        tb = setup.init_tb()
        misc = setup.get_all_misc()
        dut = setup.init_swi(misc.get('ck_role_dut', 'swi_a'))
        self.tb = tb
        self.dut = dut
        # Bind the ONE link this case needs from the bench's role contract, assert its media,
        # and take the PARTNER from that link's far end — no second lookup. Deterministic on
        # purpose: this used to be a FILL slot, and the model declared links the test never
        # used (T33235 bound 4 devices and 2 links while referencing 1 of each, so the script
        # demanded cabling for no reason). One link => exactly one partner.
        (dut.portA, self.ck_far_port, lp) = self._ck_bind_link(
            setup, dut, misc, 'copper')
        self.lp = lp

    def configure(self):
        # One-time SUITE setup, runs ONCE before all test cases. Config only — no pass/fail.
        # setup: Configure the test port for `speed auto` and `duplex auto`, and configure the partner port over its own CLI for `speed auto` and `duplex auto`.
        # setup: Restore the partner to `speed auto`/`duplex auto` and confirm the auto link re-establishes, giving an established auto-negotiated link as the precondition for the renegotiation test.
        # legacy 5000_mdi_mdix/library_5000.py lines 88-119
        dut = self.dut
        lp = self.lp
        port = dut.portA
        far = self.ck_far_port
        dut.mode(')#')
        dut.cmd('interface {}'.format(port.name))
        dut.cmd('speed auto')
        dut.cmd('duplex auto')
        dut.mode('#')
        lp.mode(')#')
        lp.cmd('interface {}'.format(far.name))
        lp.cmd('speed auto')
        lp.cmd('duplex auto')
        lp.mode('#')
        time.sleep(5)

    def tear_down(self):
        # One-time SUITE cleanup, runs ONCE after all cases. No pass/fail.
        dut = self.dut
        lp = self.lp
        port = dut.portA
        far = self.ck_far_port
        dut.mode(')#')
        dut.cmd('interface {}'.format(port.name))
        dut.cmd('speed auto')
        dut.cmd('duplex auto')
        dut.mode('#')
        lp.mode(')#')
        lp.cmd('interface {}'.format(far.name))
        lp.cmd('speed auto')
        lp.cmd('duplex auto')
        lp.mode('#')


class TestCase_1(ATTestCase.TestCase):
    testCaseDesc = "On the test SFP port with NO pluggable fitted, read the port's negotiation configuration: `show running-config interface <test port>` and `show interface <test port>`."
    testCaseRef = 'AWPTCM-T33233'
    testCaseMethod = "On the test SFP port with NO pluggable fitted, read the port's negotiation configuration: `show running-config interface <test port>` and `show interface <test port>`. | verify: Running-config shows no forced `speed` and no forced `duplex` line for the port (i.e. it is at its default), confirming the port defaults to automatic speed and duplex negotiation with no pluggable present. Describe in words: no `speed <n>` / `duplex full|half` override is configured."

    def main(self):
        # legacy 5000_mdi_mdix/test-5000.0001-CopperFixed_Straight.py lines 33-75
        self.log("STEP 1: On the test SFP port with NO pluggable fitted, read the port's negotiation configuration: `show running-config interface <test port>` and `show interface <test port>`.")
        dut = self.testSet.dut
        port = dut.portA
        dut.mode('#')
        run_cfg = dut.cmd('show running-config interface {}'.format(port.name))
        detail = dut.cmd('show interface {}'.format(port.name))
        output = run_cfg + '\n' + detail
        self.log('OBSERVED: {}'.format(output))
        # Default = no forced override: running-config carries no `speed <n>` / `duplex
        # full|half` line for the port, and show interface reports the configured values as
        # auto (the `current` line is negotiated, so we assert on `configured`).
        no_forced_speed = ('speed ' not in run_cfg)
        no_forced_duplex = ('duplex ' not in run_cfg)
        if no_forced_speed and no_forced_duplex and 'configured duplex auto' in detail and 'configured speed auto,' in detail:
            self.passed('Running-config shows no forced `speed` and no forced `duplex` line for the port (i.e. it is at its default), confirming the port defaults to automatic speed and duplex negotiation with no pluggable present. Describe in words: no `speed <n>` / `duplex full|half` override is configured.')
        else:
            self.failed('Running-config shows no forced `speed` and no forced `duplex` line for the port (i.e. it is at its default), confirming the port defaults to automatic speed and duplex negotiation with no pluggable present. Describe in words: no `speed <n>` / `duplex full|half` override is configured.')

    def tear_down(self):
        # Per-case cleanup so the next case starts clean. No pass/fail.
        pass


class TestCase_2(ATTestCase.TestCase):
    testCaseDesc = 'Prompt the operator to insert a supported pluggable into the test port, then poll `show interface <test port> status` for the link-up transition.'
    testCaseRef = 'AWPTCM-T33233'
    testCaseMethod = 'Prompt the operator to insert a supported pluggable into the test port, then poll `show interface <test port> status` for the link-up transition. | verify: After insertion the status line moves to `connected` and reports an auto-negotiated result (e.g. `a-1000`/`a-full` in the Speed/Duplex columns), confirming autonegotiation completed and the link established.'

    def main(self):
        # legacy 5000_mdi_mdix/library_5000.py lines 241-270
        self.log('STEP 2: Prompt the operator to insert a supported pluggable into the test port, then poll `show interface <test port> status` for the link-up transition.')
        # PHYSICAL: the operator acts on the hardware, then we poll for the state change.
        dut = self.testSet.dut
        port = dut.portA
        self.log('OPERATOR: Prompt the operator to insert a supported pluggable into the test port, then poll `show interface <test port> status` for the link-up transition.')
        want = 'connected'
        deadline = time.time() + 120
        output = ''
        while time.time() < deadline:
            # Scoped to ONE port, so a plain substring test here is safe.
            output = dut.cmd('show interface {} status'.format(port.name), log=False)
            if want in output:
                break
            self.log('Waiting for operator: Prompt the operator to insert a supported pluggable into the test port, then poll `show interface <test port> status` for the link-up transition.')
            time.sleep(2)
        self.log('OBSERVED: {}'.format(output))
        # Link up AND an auto-negotiated result (the `a-` prefix in the Speed/Duplex columns)
        # — this proves autonegotiation completed, not merely that a cable is in.
        if want in output and 'a-' in output:
            self.passed('After insertion the status line moves to `connected` and reports an auto-negotiated result (e.g. `a-1000`/`a-full` in the Speed/Duplex columns), confirming autonegotiation completed and the link established.')
        else:
            self.failed('After insertion the status line moves to `connected` and reports an auto-negotiated result (e.g. `a-1000`/`a-full` in the Speed/Duplex columns), confirming autonegotiation completed and the link established.')

    def tear_down(self):
        # Per-case cleanup so the next case starts clean. No pass/fail.
        pass


